      dx += Math.cos(this.time * 1.7 + e.pos.z * 0.1) * 0.25;
      dz += Math.sin(this.time * 1.3 + e.pos.x * 0.1) * 0.25;
      const l = Math.hypot(dx, dz) || 1;
      dx /= l; dz /= l;
