      this.moveEntity(e, { x: dx, z: dz }, SPECIES[e.species].speed * SPECIES[e.species].sprint * 0.97, dt);
      if (e.fleeTimer <= 0) {
        e.fleeTimer = rand(3.6, 5.4);
