      if (e.species === 'lion' && d < 23 && e.abilityReadyAt <= this.time) this.tryAbility(e);
      if (e.species === 'cheetah' && d > 7 && d < 34 && e.abilityReadyAt <= this.time) this.tryAbility(e);
    }

    // ── chase ───────────────────────────────────────────
    if (e.state === 'chase') {
