  moveEntity(e, dir, speed, dt) {
    let dx = dir.x, dz = dir.z;
    const l0 = Math.hypot(dx, dz);
    if (l0 < 0.001 || speed <= 0.01) {
      e.speedActual = Math.max(0, e.speedActual - dt * 8);
